window.docContents[36].resolve({"/rules/RG1002/#RG1002-proof-shape":{"contents":"The completed declaration keeps the same statement. Weakening the proposition until it is easy to prove changes the requirement and is a semantic review failure, even though this rule then passes.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1002: Proof holes are forbidden","header":"Required proof shape","id":"/rules/RG1002/#RG1002-proof-shape"},"/rules/RG2001/#RG2001-proof-shape":{"contents":"No proof obligation: the rule concerns the availability of the environment. The corrected run must then pass the applicable declaration and project rules.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2001: The declared Lean environment must be available","header":"Required proof shape","id":"/rules/RG2001/#RG2001-proof-shape"}});